window.QUIZ_BANK['cucumber'] = (window.QUIZ_BANK['cucumber']||[]).concat([
{id:3551,topic:'cucumber',difficulty:'beginner',question:'What is BDD (Behavior-Driven Development)?',options:['A unit testing methodology','A development approach where tests are written in plain language describing expected behavior, bridging communication between business and technical teams','A continuous integration practice','A code review method'],answer:1,explanation:'BDD focuses on software behavior from the user\'s perspective. Tests are written as scenarios in Given/When/Then format before code is written, ensuring shared understanding among developers, testers, and business stakeholders.'},
{id:3552,topic:'cucumber',difficulty:'beginner',question:'What is Gherkin?',options:['A type of pickle','A plain-text domain-specific language for writing BDD test scenarios in a human-readable format using keywords like Feature, Scenario, Given, When, Then','A testing framework','A Java library'],answer:1,explanation:'Gherkin is the language used to write Cucumber feature files. It uses structured keywords to describe behavior. It is supported in 70+ languages. The .feature extension identifies Gherkin files.'},
{id:3553,topic:'cucumber',difficulty:'beginner',question:'What is the `Feature` keyword in Gherkin?',options:['A Java annotation','The first line of a .feature file providing a high-level description of a group of related scenarios, serving as documentation for the functionality being tested','A test method marker','A configuration key'],answer:1,explanation:'Feature: User Authentication — provides a title and optional description. Multiple Scenarios or Scenario Outlines appear under one Feature. A .feature file should contain only one Feature keyword.'},
{id:3554,topic:'cucumber',difficulty:'beginner',question:'What does the `Scenario` keyword define in Gherkin?',options:['A test class','A single concrete example of the feature\'s behavior, consisting of Given/When/Then steps that describe a specific use case','A test suite','A data set'],answer:1,explanation:'Scenario: Login with valid credentials. Each Scenario is independent and represents one test case. A feature file can contain multiple Scenarios. Each Scenario should test one specific behavior.'},
{id:3555,topic:'cucumber',difficulty:'beginner',question:'What is the `Given` step in Gherkin?',options:['An assertion step','A step describing the initial context or preconditions before the action is taken — sets up the system state before the test','A verification step','A cleanup step'],answer:1,explanation:'Given describes what already exists: Given the user is on the login page. It sets up the preconditions. Multiple Given steps can be connected with And/But. Avoid action verbs in Given steps.'},
{id:3556,topic:'cucumber',difficulty:'beginner',question:'What is the `When` step in Gherkin?',options:['A precondition step','A step describing the action or event that triggers the behavior being tested','An assertion step','A background step'],answer:1,explanation:'When describes the user action: When the user enters valid credentials and clicks Login. It represents the trigger event. A scenario typically has one When step to keep it focused on a single action.'},
{id:3557,topic:'cucumber',difficulty:'beginner',question:'What is the `Then` step in Gherkin?',options:['A setup step','A step describing the expected outcome or observable result after the When action — the assertion','An action step','A cleanup step'],answer:1,explanation:'Then describes the expected result: Then the user should see the dashboard. It corresponds to assertions in test code. Use observable outcomes, not internal system state.'},
{id:3558,topic:'cucumber',difficulty:'beginner',question:'What is the `And` / `But` keyword in Gherkin?',options:['A logical operator','Continuation keywords that replace repeated Given/When/Then keywords to improve readability: And = "and also"; But = "however"','An optional step','A data keyword'],answer:1,explanation:'And/But avoid repetitive Given/Given/Given. And connects same-type steps: Given... And... And... But provides a contrasting step: Then the user is logged in But the session expires after 30 minutes.'},
{id:3559,topic:'cucumber',difficulty:'beginner',question:'What is a Cucumber `Feature` file?',options:['A Java source file','A plain text file with .feature extension containing Gherkin-written BDD scenarios — the executable specification','A configuration file','A report file'],answer:1,explanation:'.feature files contain the business-readable test scenarios. They are stored in src/test/resources. Cucumber discovers them at runtime based on @CucumberOptions features path. They serve as living documentation.'},
{id:3560,topic:'cucumber',difficulty:'beginner',question:'What is a step definition in Cucumber?',options:['A Gherkin keyword','A Java (or other language) method annotated with @Given/@When/@Then that maps to a Gherkin step via a regex or Cucumber expression, implementing the test logic','A test class annotation','A feature file section'],answer:1,explanation:'Step definitions bridge Gherkin steps to code: @When("^the user clicks {string}$") public void userClicks(String btn){...}. Cucumber matches each step to its definition using the pattern.'},
{id:3561,topic:'cucumber',difficulty:'beginner',question:'What is the `Background` keyword in Gherkin?',options:['A CSS term','A set of steps that run before EACH scenario in a feature file — used for common preconditions shared across all scenarios','A data section','A tagged scenario'],answer:1,explanation:'Background: Given I am logged in as admin. This runs before every Scenario/Scenario Outline in the file. Keeps scenarios DRY. Unlike @Before hooks, Background is visible in the feature file and serves as documentation.'},
{id:3562,topic:'cucumber',difficulty:'intermediate',question:'What is `Scenario Outline` in Gherkin?',options:['A named scenario','A parameterized scenario template that runs once for each row in an Examples table, substituting <placeholder> values from the table columns','A scenario with Background','A multi-step scenario'],answer:1,explanation:'Scenario Outline + Examples enables data-driven tests: Scenario Outline: Login as <role>; Given I am <role>; Examples: |role|; |admin|; |user|. Each row creates one test execution.'},
{id:3563,topic:'cucumber',difficulty:'intermediate',question:'What is the `Examples` table in Cucumber?',options:['A documentation table','A data table under a Scenario Outline that provides multiple sets of test data, with the header row defining parameter names referenced by <placeholders>','A step data table','An output table'],answer:1,explanation:'Examples: | username | password | | alice | pass123 | | bob | secret |. Each row creates one Scenario Outline execution with those values substituted for <username> and <password>.'},
{id:3564,topic:'cucumber',difficulty:'intermediate',question:'What is a Cucumber DataTable?',options:['A spreadsheet format','A table passed directly in a Gherkin step that provides multi-row/column data to the step definition, mapped as List<Map<String,String>>, Map, or List<List<String>>','An Examples alternative','A JSON input'],answer:1,explanation:'DataTable in step: Given the following users: | name | age | | Alice | 30 |. In step definition: public void users(DataTable dt){ List<Map<String,String>> rows = dt.asMaps(); }. Powerful for bulk test data.'},
{id:3565,topic:'cucumber',difficulty:'intermediate',question:'What is a DocString in Cucumber?',options:['A Javadoc comment','A multi-line string passed to a step definition using triple-quoted """ delimiters, typically used for JSON, XML, SQL, or any multi-line text input','A step documentation comment','A feature file header'],answer:1,explanation:'DocString: Given the request body is: """ { "user": "alice" } """. Step receives it as a String parameter. Useful for JSON/XML payloads in API tests. Indentation relative to the triple quotes is stripped.'},
{id:3566,topic:'cucumber',difficulty:'intermediate',question:'How do you set up Cucumber-JVM with Maven?',options:['No Maven support','Add io.cucumber:cucumber-java, cucumber-junit or cucumber-testng, and cucumber-picocontainer dependencies; configure a runner class or use Maven Surefire with the Cucumber plugin','Use Gradle only','Configure in pom.xml only'],answer:1,explanation:'pom.xml: io.cucumber:cucumber-java:7.x, cucumber-testng:7.x, cucumber-picocontainer:7.x. Create a runner class with @CucumberOptions. Run: mvn test. Or use io.cucumber:cucumber-junit-platform-engine for JUnit 5.'},
{id:3567,topic:'cucumber',difficulty:'intermediate',question:'What is `@CucumberOptions` annotation?',options:['A TestNG annotation','An annotation on the Cucumber runner class that configures test execution: features path, glue (step definition packages), tags, plugins, and more','A JUnit annotation','A Spring annotation'],answer:1,explanation:'@CucumberOptions(features="src/test/resources/features", glue="com.tests.steps", tags="@smoke", plugin={"pretty","html:target/reports"}). Placed on a class annotated with @RunWith(Cucumber.class) or @Suite.'},
{id:3568,topic:'cucumber',difficulty:'intermediate',question:'What is the `glue` option in @CucumberOptions?',options:['A dependency injection config','Specifies the package(s) where Cucumber should look for step definitions, hooks, and parameter type configurations','The features directory','The plugin list'],answer:1,explanation:'glue="com.myapp.steps" — Cucumber scans this package for classes with @Given/@When/@Then/@Before/@After. Multiple packages: glue={"com.steps","com.hooks"}. Incorrect glue causes "Undefined step" errors.'},
{id:3569,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber JUnit 4 runner class setup?',options:['@RunWith(JUnit4.class)','@RunWith(Cucumber.class) on an empty class combined with @CucumberOptions — Cucumber uses this class as the entry point to discover and run feature files','@Suite runner','A main() method'],answer:1,explanation:'@RunWith(Cucumber.class) @CucumberOptions(features="src/test/resources", glue="com.steps") public class RunCucumberTests {} — an empty class. Maven Surefire picks it up and runs all features.'},
{id:3570,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber JUnit 5 Platform Suite runner?',options:['Not supported','Using @Suite, @IncludeEngines("cucumber"), and @ConfigurationParameter to configure features and glue for JUnit 5 Platform, replacing the JUnit 4 @RunWith approach','@CucumberOptions only','A plugin-based runner'],answer:1,explanation:'@Suite @IncludeEngines("cucumber") @ConfigurationParameter(key=GLUE_PROPERTY_NAME, value="com.steps") @ConfigurationParameter(key=FEATURES_PROPERTY_NAME, value="src/test/resources"). JUnit 5 approach using cucumber-junit-platform-engine.'},
{id:3571,topic:'cucumber',difficulty:'intermediate',question:'What are Cucumber tags and how are they used?',options:['HTML tags','Annotations in Gherkin (@tagName) applied to Features/Scenarios that allow filtering which tests run via @CucumberOptions tags or command-line arguments','Java annotations','Test groups'],answer:1,explanation:'@smoke, @regression, @wip — tags filter test execution. @CucumberOptions(tags="@smoke and not @wip") runs smoke tests excluding wip. Tags can be on Feature (inherited by all Scenarios) or individual Scenarios.'},
{id:3572,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber tag expression syntax?',options:['Comma-separated list','Boolean expressions using and, or, not: "@smoke and not @wip", "@regression or @smoke", "not @skip"','Space-separated list','A regex pattern'],answer:1,explanation:'Tag expressions: "@smoke and @critical" (both), "@smoke or @regression" (either), "not @wip" (exclusion), "@smoke and not @flaky". Precedence: not > and > or. Parentheses for grouping.'},
{id:3573,topic:'cucumber',difficulty:'intermediate',question:'What does `@Before` hook do in Cucumber?',options:['Marks a test method','A method annotated with @Before (io.cucumber.java.Before) that runs before each scenario — used for setup like opening browsers or initializing test data','A JUnit lifecycle method','A TestNG lifecycle method'],answer:1,explanation:'@Before public void setUp() { driver = new ChromeDriver(); }. Runs before each Scenario. @Before(order=1) controls order (lower = first). @Before("@login") runs only for scenarios tagged @login.'},
{id:3574,topic:'cucumber',difficulty:'intermediate',question:'What does `@After` hook do in Cucumber?',options:['Marks a cleanup test','A method annotated with @After (io.cucumber.java.After) that runs after each scenario — used for cleanup like closing browsers, capturing screenshots on failure','A JUnit @After method','A TestNG @AfterMethod'],answer:1,explanation:'@After public void tearDown(Scenario scenario) { if(scenario.isFailed()) captureScreenshot(); driver.quit(); }. The Scenario parameter provides result info. @After always runs even if the scenario fails.'},
{id:3575,topic:'cucumber',difficulty:'intermediate',question:'What is `@BeforeStep` and `@AfterStep` in Cucumber?',options:['Step-level JUnit annotations','Hooks that run before/after EACH STEP (not each scenario) — useful for logging every step or taking screenshots after each interaction','Feature-level hooks','Suite-level hooks'],answer:1,explanation:'@BeforeStep and @AfterStep (Cucumber 6+) run before/after every individual step. Useful for step-level logging or screenshots. More granular than @Before/@After which are scenario-level.'},
{id:3576,topic:'cucumber',difficulty:'intermediate',question:'What is tagged hook ordering in Cucumber?',options:['Alphabetical order','Hooks can be tagged: @Before("@api") only runs for @api scenarios. order=N controls execution order when multiple hooks exist: lower order number runs first for @Before, last for @After.','Random order','Priority-based'],answer:1,explanation:'@Before(value="@api", order=1) and @Before(value="@api", order=2) — order 1 runs first. For @After, order=1 runs last (reversed). Tagged hooks only apply to matching scenarios, reducing unnecessary setup/teardown.'},
{id:3577,topic:'cucumber',difficulty:'intermediate',question:'What is PicoContainer dependency injection in Cucumber?',options:['A Spring alternative','A lightweight DI framework (cucumber-picocontainer) that shares state between step definition classes by injecting constructor parameters automatically','A manual object passing method','A global state container'],answer:1,explanation:'PicoContainer creates one instance of each step class per scenario. Classes sharing state declare it as a constructor parameter: public LoginSteps(SharedState state). PicoContainer creates and injects SharedState automatically.'},
{id:3578,topic:'cucumber',difficulty:'intermediate',question:'What is the World object concept in Cucumber?',options:['A global variable','A shared state object injected into step definition classes for a scenario\'s duration — in Ruby Cucumber it is the test context; in JVM Cucumber, achieved via DI (PicoContainer/Spring)','An HTTP client','A browser instance'],answer:1,explanation:'In Ruby Cucumber, every step definition is a method on the World object (a shared context). In JVM Cucumber, share state via constructor injection with PicoContainer or Spring, effectively giving each scenario its own "World".'},
{id:3579,topic:'cucumber',difficulty:'intermediate',question:'What is the `dryRun` option in @CucumberOptions?',options:['Runs tests without a browser','Checks that all Gherkin steps have matching step definitions without actually executing them — reveals undefined/unimplemented steps quickly','Skips all tests','Runs in headless mode'],answer:1,explanation:'dryRun=true: Cucumber validates step mappings without execution. Outputs "PENDING" or "UNDEFINED" for unmatched steps. Useful when writing feature files first to identify missing step definitions.'},
{id:3580,topic:'cucumber',difficulty:'intermediate',question:'What is the `monochrome` option in @CucumberOptions?',options:['Disables colors','Makes console output more readable by removing unnecessary special characters and ANSI color codes from the output','A report format','A verbose mode'],answer:1,explanation:'monochrome=true removes ANSI escape codes that appear as garbage characters in some consoles and CI logs. Default false. Recommended for CI environments where color codes cause log readability issues.'},
{id:3581,topic:'cucumber',difficulty:'intermediate',question:'What is the `publish` option in Cucumber?',options:['Publishes to Maven','Uploads test results to the Cucumber Reports portal at reports.cucumber.io for persistent, shareable HTML reports after a run','Publishes to npm','A CI notification'],answer:1,explanation:'plugin={"io.cucumber.core.plugin.SerenityReporter"} or publish=true. When publish=true, Cucumber generates a public URL for the report at reports.cucumber.io. Requires agreement to their terms of service.'},
{id:3582,topic:'cucumber',difficulty:'intermediate',question:'What is a Cucumber Expression?',options:['A Java regex pattern','A Cucumber-specific expression syntax that is more readable than regex: {string}, {int}, {float}, {word}, {bigdecimal}. Preferred over regex for step parameters.','An XPath expression','A Gherkin keyword'],answer:1,explanation:'Cucumber Expression: "the user enters {string} in the {word} field" matches: the user enters "alice" in the username field. Parameters {string} = quoted string, {int} = integer, {word} = one word without spaces.'},
{id:3583,topic:'cucumber',difficulty:'intermediate',question:'What is the difference between Cucumber Expressions and Regular Expressions?',options:['They are identical','Cucumber Expressions ({int}, {string}) are simpler and more readable; Regex (^the user (.+)$) are more powerful and flexible. Both work in step definitions.','Regex is deprecated','Cucumber Expressions support Java only'],answer:1,explanation:'Cucumber Expressions: human-readable built-in types. Regex: full power but verbose. If expression starts with ^ or ends with $, Cucumber treats it as regex. Otherwise, it is a Cucumber Expression.'},
{id:3584,topic:'cucumber',difficulty:'intermediate',question:'What is `@ParameterType` in Cucumber?',options:['A TestNG annotation','A custom parameter type annotation that maps a named type to a regex and converts it to a Java object: @ParameterType("admin|user") public Role role(String roleName)','A data type annotation','A step modifier'],answer:1,explanation:'@ParameterType("admin|user|guest") public Role role(String s) { return Role.valueOf(s.toUpperCase()); } enables {role} in expressions: "When I log in as {role}". Type safety and reusability in step definitions.'},
{id:3585,topic:'cucumber',difficulty:'intermediate',question:'How does Cucumber handle ambiguous step definitions?',options:['Picks the first match','Throws an AmbiguousStepDefinitionsException when multiple step definitions match the same Gherkin step. Each step must match exactly one definition.','Runs both definitions','Skips the step'],answer:1,explanation:'Ambiguous steps cause runtime failure. Fix by making patterns more specific or refactoring to avoid overlap. Cucumber does not allow ambiguous matches by design to ensure deterministic test execution.'},
{id:3586,topic:'cucumber',difficulty:'intermediate',question:'What is an undefined step in Cucumber?',options:['A skipped step','A Gherkin step that has no matching step definition. Cucumber marks it UNDEFINED and suggests a snippet to implement. The scenario is also marked as UNDEFINED/PENDING.','An empty step','A background step'],answer:1,explanation:'Undefined steps: Cucumber prints a snippet like: @When("the user clicks {string}") public void theUserClicks(String arg0) { // TODO }. Implement these to make scenarios executable.'},
{id:3587,topic:'cucumber',difficulty:'intermediate',question:'What is a pending step in Cucumber?',options:['A queued step','A step definition that throws PendingException (or is not implemented), causing the scenario to be marked PENDING — similar to @Ignore, signals work in progress','A skipped step','An undefined step'],answer:1,explanation:'throw new PendingException() in a step definition marks the scenario as PENDING. Cucumber reports it as skipped. Useful as a placeholder when step definitions are written before implementation.'},
{id:3588,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber `plugin` option?',options:['A Maven plugin config','Configures output formatters: "pretty" (console), "html:target/reports", "json:target/report.json", "junit:target/results.xml", "rerun:target/rerun.txt"','A Java plugin API','A Gherkin formatter'],answer:1,explanation:'plugin={"pretty","html:target/cucumber-reports","json:target/cucumber.json","junit:target/cucumber.xml","rerun:target/rerun.txt"}. Multiple plugins can be active simultaneously. Each produces a different output format.'},
{id:3589,topic:'cucumber',difficulty:'intermediate',question:'What does the `rerun` plugin do in Cucumber?',options:['Reruns all tests','Writes the paths of failed scenarios to a text file in @path:line format, allowing only failed scenarios to be rerun in the next execution','Retries failed scenarios immediately','Runs tests in reverse'],answer:1,explanation:'plugin="rerun:target/rerun.txt" writes: features/login.feature:15 for failed scenarios. Rerun: @CucumberOptions(features="@target/rerun.txt"). CI pipelines use this for selective rerun of failures.'},
{id:3590,topic:'cucumber',difficulty:'intermediate',question:'What does the Cucumber `pretty` plugin output?',options:['A formatted HTML report','A colored, human-readable console output showing each step with its status (passed/failed/pending/undefined), including snippets for undefined steps','A JSON report','A plain text report'],answer:1,explanation:'"pretty" formats console output with colors: green (passed), red (failed), yellow (pending). Shows the feature file structure with step-by-step execution. The most readable console formatter.'},
{id:3591,topic:'cucumber',difficulty:'intermediate',question:'What does the Cucumber `html` plugin generate?',options:['Sends HTML emails','Generates an HTML report at the specified path showing scenario results with pass/fail status, step details, and embedded content','A Javadoc report','A Maven site report'],answer:1,explanation:'plugin="html:target/cucumber-reports" creates an HTML report directory. Contains index.html with pass/fail counts, scenario details, and embedded screenshots/output. Self-contained, shareable report.'},
{id:3592,topic:'cucumber',difficulty:'intermediate',question:'What does the Cucumber `json` plugin generate?',options:['A config file','A JSON report file containing all execution results in a structured format used by third-party tools like Jenkins Cucumber Plugin, Allure, and ExtentReports','A JSON schema','An API mock'],answer:1,explanation:'cucumber.json is the standard interchange format. Jenkins Cucumber Plugin visualizes it. Allure and ExtentReports read it. Contains: feature name, scenarios, steps, status, duration, embeddings.'},
{id:3593,topic:'cucumber',difficulty:'intermediate',question:'What does the Cucumber `junit` plugin generate?',options:['JUnit source code','A JUnit-compatible XML report that CI servers (Jenkins, Azure DevOps, GitLab CI) can parse to display test results and trends','A JUnit runner','A surefire report'],answer:1,explanation:'plugin="junit:target/cucumber-junit.xml" creates XML in the JUnit format. Most CI servers natively understand JUnit XML. Essential for test trend reporting in CI/CD pipelines.'},
{id:3594,topic:'cucumber',difficulty:'intermediate',question:'How do you run only tagged scenarios via Maven command line?',options:['Cannot filter from command line','Using -Dcucumber.filter.tags="@smoke" system property overrides @CucumberOptions tags at runtime without modifying code','Using a separate pom.xml','Using Maven profiles only'],answer:1,explanation:'mvn test -Dcucumber.filter.tags="@smoke and not @wip" overrides the tags in @CucumberOptions. Enables dynamic test selection in CI pipelines without code changes.'},
{id:3595,topic:'cucumber',difficulty:'intermediate',question:'What is the `strict` option in Cucumber (now default behavior)?',options:['Enforces naming conventions','In older Cucumber versions, strict=true made the build fail for undefined/pending steps. Cucumber 7+ is strict by default: undefined steps always cause failure.','A formatting option','A data validation option'],answer:1,explanation:'Cucumber 7+ removed the strict option as it became the default. Undefined or pending steps always cause the scenario and build to fail. No step can be silently unimplemented in CI.'},
{id:3596,topic:'cucumber',difficulty:'intermediate',question:'What is Cucumber parallel execution?',options:['Running the same test twice','Running multiple scenarios or features concurrently using Maven Surefire fork count, the cucumber-jvm-parallel-plugin, or JUnit 5 parallel execution configuration','A TestNG feature only','A CI/CD feature'],answer:1,explanation:'JUnit 5: cucumber.execution.parallel.enabled=true in junit-platform.properties. Maven Surefire: <forkCount>4</forkCount>. Requires thread-safe step definitions and isolated state per thread (ThreadLocal for WebDriver).'},
{id:3597,topic:'cucumber',difficulty:'intermediate',question:'How do you make Cucumber step definitions thread-safe for parallel execution?',options:['Use static variables','Use ThreadLocal for shared resources (WebDriver, DB connections): ThreadLocal<WebDriver> driver = new ThreadLocal<>() — each thread gets its own instance','Use synchronized methods','Use a single shared driver'],answer:1,explanation:'ThreadLocal<WebDriver> ensures each parallel thread has its own WebDriver instance. PicoContainer creates new instances per scenario, enabling natural thread safety. Avoid static mutable state in step definitions.'},
{id:3598,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber `@CucumberOptions` `features` attribute?',options:['Feature flags','Specifies the path(s) to the .feature files or directories: features="src/test/resources/features". Can also be a specific file or @rerun.txt file path.','A class package path','A feature toggle'],answer:1,explanation:'features="src/test/resources/features" finds all .feature files recursively. features="src/test/resources/features/login.feature" runs one file. features="@target/rerun.txt" reruns failures from a previous run.'},
{id:3599,topic:'cucumber',difficulty:'intermediate',question:'What is the Scenario `isFailed()` method used for?',options:['Marks scenario as failed','Available in @After hook via Scenario parameter: scenario.isFailed() returns true if any step failed, enabling conditional actions like screenshot capture on failure','A step assertion method','A hook return value'],answer:1,explanation:'@After public void after(Scenario sc){ if(sc.isFailed()){ byte[] screenshot=((TakesScreenshot)driver).getScreenshotAs(OutputType.BYTES); sc.attach(screenshot,"image/png","Screenshot"); } }'},
{id:3600,topic:'cucumber',difficulty:'intermediate',question:'What is `scenario.attach()` in Cucumber?',options:['Attaches a file to the issue tracker','Embeds data (screenshots, HTML, plain text) into the Cucumber report as an attachment, visible in the HTML report','Attaches a listener','Links a scenario to a step'],answer:1,explanation:'sc.attach(data, mimeType, name): sc.attach(pngBytes,"image/png","Failure Screenshot") embeds a screenshot. sc.attach("text","text/plain","Log") embeds text. Visible in the HTML report alongside the scenario.'},
{id:3601,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber `Name` filter?',options:['A feature name filter','--name or cucumber.filter.name system property filters scenarios by name regex: -Dcucumber.filter.name="login" runs only scenarios with "login" in their name','A tag filter','A method filter'],answer:1,explanation:'mvn test -Dcucumber.filter.name="Valid Login" — case-sensitive regex matching scenario names. Useful for running a specific scenario by name during debugging without knowing the line number.'},
{id:3602,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber `glue` best practice?',options:['Put all steps in one class','Organize step definitions in cohesive classes by domain/feature area (LoginSteps, CartSteps, CheckoutSteps) rather than one monolithic class or per-feature classes','Use one package only','Put steps in test resources'],answer:1,explanation:'Group step definitions by domain concern. Avoid one giant StepDefs class. Avoid per-feature step classes (causes duplication). Domain-based organization (LoginSteps, ProductSteps) promotes reuse and maintainability.'},
{id:3603,topic:'cucumber',difficulty:'intermediate',question:'How does Cucumber handle state between steps?',options:['Via global variables','Via dependency injection: steps share a context object passed through constructor injection (PicoContainer) or via Spring @Autowired beans scoped to the scenario','Via static fields','Via method chaining'],answer:1,explanation:'Never use static fields for step state — causes parallel execution failures. Use constructor DI: class LoginSteps(TestContext ctx) — ctx is shared across all step classes. PicoContainer creates one ctx per scenario.'},
{id:3604,topic:'cucumber',difficulty:'intermediate',question:'What is a Cucumber step definition snippet?',options:['A code example in the feature file','Auto-generated Java method skeleton printed by Cucumber when an undefined step is found, ready to be pasted into a step definition class','A Gherkin step template','A code comment'],answer:1,explanation:'For undefined step "When the user clicks submit", Cucumber prints: @When("the user clicks submit") public void theUserClicksSubmit() { // Write code here }. Copy-paste and implement.'},
{id:3605,topic:'cucumber',difficulty:'intermediate',question:'What is the difference between Scenario Outline and DataTable?',options:['They are identical','Scenario Outline + Examples runs the whole scenario once per row (multiple scenario executions). DataTable passes a table to ONE step (one scenario execution with multiple data rows in one step).','DataTable is deprecated','Scenario Outline is for API tests'],answer:1,explanation:'Scenario Outline: multiple scenario runs. DataTable: multiple data rows in one step call. Use Scenario Outline when each data set needs full Given/When/Then. Use DataTable when one step needs structured data.'},
{id:3606,topic:'cucumber',difficulty:'intermediate',question:'How do you convert a DataTable to a List of Maps in Cucumber-JVM?',options:['Automatically converted','Call dt.asMaps() which returns List<Map<String,String>> where each map represents a row with header-keyed values','Use dt.toList()','Call dt.getData()'],answer:1,explanation:'Given step receives DataTable dt. List<Map<String,String>> rows = dt.asMaps(); for(Map<String,String> row : rows){ String name = row.get("name"); }. The header row becomes the map keys.'},
{id:3607,topic:'cucumber',difficulty:'beginner',question:'What file extension do Cucumber feature files use?',options:['.test','.feature','.gherkin','.spec'],answer:1,explanation:'.feature extension is required. Cucumber\'s test framework discovers files with this extension when scanning the features path. Files may be organized in subdirectories.'},
{id:3608,topic:'cucumber',difficulty:'intermediate',question:'What is the `@io.cucumber.java.After` vs `@org.junit.After` in Cucumber?',options:['They are identical','io.cucumber.java.After runs after each Cucumber Scenario; org.junit.After runs after each JUnit test method. In Cucumber, use the Cucumber annotation for scenario-level lifecycle.','JUnit @After is preferred','They conflict if both are used'],answer:1,explanation:'Always use io.cucumber.java.Before/After in Cucumber step definition classes, not JUnit/TestNG annotations. Mixing can cause unexpected execution order or double execution.'},
{id:3609,topic:'cucumber',difficulty:'intermediate',question:'What does `@CucumberOptions(snippetType=SnippetType.CAMELCASE)` do?',options:['Converts feature names to camelCase','Configures the auto-generated snippet style for undefined steps: CAMELCASE produces void theUserEntersText(), UNDERSCORE produces void the_user_enters_text()','Sets the naming convention','A deprecated option'],answer:1,explanation:'snippetType controls generated snippet method naming: CAMELCASE (default Java convention) or UNDERSCORE (Python/Ruby convention). Purely cosmetic for auto-generated stub methods.'},
{id:3610,topic:'cucumber',difficulty:'intermediate',question:'How do you pass a list to a Cucumber step using Gherkin?',options:['Use DataTable only','Comma-separated string in a step that is parsed in Java, or a DataTable with one column: | item1 | | item2 | mapped with dt.asList()','Use JSON in DocString','Use an Examples table'],answer:1,explanation:'When the shopping cart contains: | Apple | | Banana | | Cherry |. In step: public void cart(DataTable dt){ List<String> items = dt.asList(); }. Single-column DataTable maps to List<String>.'},
{id:3611,topic:'cucumber',difficulty:'intermediate',question:'What is Cucumber Living Documentation?',options:['Documentation written in Gherkin','Feature files as executable specifications that serve as always-up-to-date documentation of system behavior, generated into HTML docs by tools like Pickles or Serenity BDD','A Javadoc format','A static site generator'],answer:1,explanation:'Living Documentation: feature files describe business behavior, tests validate it, reports show current status. Tools like Pickles (pickles-doc.github.io) and Serenity BDD generate browsable documentation from .feature files.'},
{id:3612,topic:'cucumber',difficulty:'intermediate',question:'What is a Cucumber anti-pattern: "Steps that are too implementation-specific"?',options:['A code smell only','Writing Given/When/Then steps that describe HOW the system works (click button id="submit") rather than WHAT the business behavior is (submit the form). Tightly couples tests to implementation.','A valid practice','A performance issue'],answer:1,explanation:'Avoid: Given I click the element with xpath "//button[@id=\'btn\']". Prefer: Given I submit the login form. Implementation details belong in step definitions, not Gherkin. Gherkin should be readable by non-technical stakeholders.'},
{id:3613,topic:'cucumber',difficulty:'intermediate',question:'What is the declarative vs imperative Gherkin style?',options:['No difference','Imperative: describes HOW actions are performed step-by-step (enter username, enter password, click login). Declarative: describes WHAT the behavior is (authenticate as admin). Declarative is preferred in BDD.','Declarative is deprecated','Imperative is more readable'],answer:1,explanation:'Declarative: "When the user logs in with admin credentials" hides implementation details. Imperative: "When I enter admin@test.com... And I enter password... And I click Login" exposes UI details. Declarative improves scenario longevity.'},
{id:3614,topic:'cucumber',difficulty:'intermediate',question:'What is Cucumber scenario independence?',options:['Scenarios run in alphabetical order','Each scenario should be able to run independently in any order without depending on state left by previous scenarios. Shared state between scenarios causes flaky tests.','A parallel execution setting','A tag filter'],answer:1,explanation:'Each scenario sets up its own state in Given steps or @Before hooks. Scenarios should not depend on database state left by previous tests. Use @Before to reset state, @After to clean up.'},
{id:3615,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber `@Before` hook scope vs Background?',options:['They are identical','@Before hook is Java code running before each scenario (invisible in reports, suitable for driver init). Background is Gherkin steps running before each scenario (visible in reports, part of the specification).','Background runs first','@Before is for classes'],answer:1,explanation:'Background is living documentation — shows business preconditions. @Before is technical setup — opens browsers, sets up mocks. Use both: Background for business context, @Before for technical setup. Both run before each scenario.'},
{id:3616,topic:'cucumber',difficulty:'intermediate',question:'What is a feature file organization best practice?',options:['One feature file for all tests','One feature file per functional area or user story. Keep feature files focused. Use subdirectories: features/auth/, features/cart/, features/checkout/. Limit to 10-15 scenarios per feature.','Random organization','Organize by test type'],answer:1,explanation:'Feature files are part of your specification — organize them to reflect your domain model. Too many scenarios in one feature makes it unwieldy. Group by feature/user story for clarity and maintainability.'},
{id:3617,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber `@Ignore` equivalent?',options:['@Ignore annotation','@wip tag with a configured tag expression to exclude it: @CucumberOptions(tags="not @wip"). Or use the tag @ignore. No built-in @Ignore — tags and expressions handle this.','@Test(enabled=false)','Commenting out the scenario'],answer:1,explanation:'Add @wip or @ignore tag to the scenario. Configure: tags="not @wip". This cleanly excludes scenarios without deleting them. Communicate WHY it is ignored via a comment in the feature file.'},
{id:3618,topic:'cucumber',difficulty:'intermediate',question:'What is Cucumber step reuse?',options:['Duplicating steps','Writing step definitions generic enough to be used across multiple feature files — the key benefit of BDD. One @When("I click {string}") step handles all button clicks.','Importing steps from another project','Step definition inheritance'],answer:1,explanation:'Generic steps like @When("I navigate to {string}") and @Then("the page title should be {string}") can be used in any feature file. Keep steps generic and avoid feature-specific implementations in core steps.'},
{id:3619,topic:'cucumber',difficulty:'intermediate',question:'What are Cucumber expressions built-in parameter types?',options:['{string} only','Built-in types: {int} (32-bit integer), {long}, {float}, {double}, {byte}, {short}, {biginteger}, {bigdecimal}, {word} (no spaces), {string} (quoted), {} (anonymous - matches anything)','Only {string} and {int}','Custom types only'],answer:1,explanation:'Full list: {int} matches 32-bit integer, {long} 64-bit, {float} 32-bit float, {double} 64-bit, {biginteger}, {bigdecimal}, {byte}, {short}, {word} (one word no whitespace), {string} (single or double-quoted), {} matches any string.'},
{id:3620,topic:'cucumber',difficulty:'intermediate',question:'How do you add a comment in a Gherkin feature file?',options:['// comment','# comment — lines starting with # are comments in Gherkin and are ignored by Cucumber','/* comment */','<!-- comment -->'],answer:1,explanation:'# This is a Gherkin comment. Comments can appear on their own line anywhere in the feature file. They cannot appear mid-step. Use comments to document intent, jira IDs, or exclusion reasons.'},
{id:3621,topic:'cucumber',difficulty:'intermediate',question:'What is the `@Suite` annotation approach for Cucumber JUnit 5?',options:['A TestNG runner','The JUnit 5 Platform Suite approach: @Suite @IncludeEngines("cucumber") class RunCucumberTests{} with junit-platform.properties configuring features, glue, and plugin settings','A Spring Boot runner','A Maven Surefire config'],answer:1,explanation:'junit-platform.properties: cucumber.features=src/test/resources; cucumber.glue=com.steps; cucumber.plugin=pretty,html:target/reports. The @Suite class is empty — all config is in junit-platform.properties.'},
{id:3622,topic:'cucumber',difficulty:'advanced',question:'What is the Cucumber `ObjectFactory` interface?',options:['A test object creator','Allows providing a custom factory for creating step definition class instances, enabling integration with DI frameworks like Spring or Guice beyond the built-in PicoContainer','An abstract step factory','A runner factory'],answer:1,explanation:'Implement ObjectFactory: void start(), void stop(), <T> T getInstance(Class<T> type). Use io.cucumber.core.backend.ObjectFactory SPI. Enables custom scope management (e.g., Spring application context per scenario).'},
{id:3623,topic:'cucumber',difficulty:'advanced',question:'What is the difference between PicoContainer and Spring DI in Cucumber?',options:['They are identical','PicoContainer: lightweight, constructor injection, one instance per scenario, zero configuration. Spring: full Spring context, supports @Autowired, application context can be shared or reset per scenario.','Spring is always better','PicoContainer is deprecated'],answer:1,explanation:'PicoContainer (cucumber-picocontainer): minimal setup, perfect for most cases. Spring (cucumber-spring): use @SpringBootTest for full context, enables testing Spring beans. Choose based on project needs.'},
{id:3624,topic:'cucumber',difficulty:'advanced',question:'What is `@SpringBootTest` usage in Cucumber?',options:['Only for unit tests','Annotate a step class or a CucumberContextConfiguration class with @CucumberContextConfiguration @SpringBootTest to load the full Spring context once per test run for all scenarios','Annotate the runner class','Load context per scenario'],answer:1,explanation:'@CucumberContextConfiguration @SpringBootTest class CucumberSpringConfig{}. This configuration loads once. @DirtiesContext reloads the context. Beans @Autowired in step definition classes are Spring-managed.'},
{id:3625,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber `order` attribute on hooks?',options:['Execution priority only','Controls execution order when multiple @Before/@After hooks exist: lower number = earlier for @Before, lower number = later for @After. Default order is 10000.','A timeout setting','A parallel setting'],answer:1,explanation:'Multiple @Before hooks: order=1 runs before order=2. Multiple @After hooks: order=1 runs last (reversed, like a stack). Ensures correct setup/teardown sequence when hooks are spread across multiple classes.'},
{id:3626,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber `@BeforeSuite` equivalent in Cucumber-JVM?',options:['@BeforeSuite annotation','There is no @BeforeSuite in Cucumber-JVM. Use @BeforeAll in JUnit 5 in the runner class, or a JUnit ClassRule, or Spring @BeforeAll + @SpringBootTest — Cucumber has no native suite-level hooks','@CucumberOptions setup','A listener interface'],answer:1,explanation:'Cucumber-JVM only has scenario-level hooks (@Before/@After). For suite-level setup, use: JUnit 5 @BeforeAll in the runner class, Spring application context lifecycle, or a custom EventListener registered via SPI.'},
{id:3627,topic:'cucumber',difficulty:'intermediate',question:'What is the cucumber-picocontainer dependency purpose?',options:['A build tool','Provides the PicoContainer DI implementation for Cucumber-JVM, enabling automatic constructor injection of shared state objects between step definition classes within a scenario','A report generator','A Cucumber plugin'],answer:1,explanation:'Without a DI module, each step class is instantiated independently. With cucumber-picocontainer, Cucumber creates a shared object graph per scenario. Add: io.cucumber:cucumber-picocontainer to pom.xml.'},
{id:3628,topic:'cucumber',difficulty:'intermediate',question:'What is the `CucumberOptions.name` filter?',options:['Sets the suite name','Filters scenarios to run by matching their name with the provided regex: @CucumberOptions(name={"Login.*"}) runs only scenarios whose names start with "Login"','Sets the feature name','A tag alternative'],answer:1,explanation:'name={"^Login"} filter uses regex matching against scenario names. Useful for running specific scenarios during development. Combined with dryRun=true to validate step coverage for specific scenarios.'},
{id:3629,topic:'cucumber',difficulty:'intermediate',question:'How do you configure the Cucumber HTML report path?',options:['In pom.xml only','In @CucumberOptions plugin: plugin={"html:target/cucumber-reports/report.html"} or plugin={"html:target/cucumber-reports"} for a directory-based report','In feature file','Via a separate config file'],answer:1,explanation:'The path after the colon is the output location. "html:target/reports" creates target/reports/ directory. Multiple plugins can run simultaneously. JUnit XML for CI, HTML for human review, JSON for tool integration.'},
{id:3630,topic:'cucumber',difficulty:'advanced',question:'What is the Cucumber EventBus and how to use custom plugins?',options:['A Kafka integration','Cucumber\'s internal event system where plugins subscribe to events (TestRunStarted, TestCaseStarted, TestStepFinished, etc.) via the EventBus to build custom reporters','A Spring event bus','A step event system'],answer:1,explanation:'Implement Plugin interface and subscribe to EventBus. Events: TestRunStarted, TestRunFinished, TestCaseStarted, TestCaseFinished, TestStepStarted, TestStepFinished, SnippetsSuggestedEvent. Register via @CucumberOptions plugin or SPI.'},
{id:3631,topic:'cucumber',difficulty:'intermediate',question:'What is `scenario.getName()` and `scenario.getId()` used for?',options:['Debug methods','Available in @Before/@After hooks via the Scenario parameter: getName() returns the scenario title for logging; getId() returns a unique identifier for the scenario','Step definition methods','Feature file accessors'],answer:1,explanation:'@Before(order=1) public void setup(Scenario s){ log.info("Starting: "+s.getName()); ExtentReports test = extent.createTest(s.getName()); testReport.set(test); }'},
{id:3632,topic:'cucumber',difficulty:'intermediate',question:'What is the `@CucumberOptions` `stepNotifications` attribute?',options:['Enables step timing','When true, sends BeforeStep/AfterStep events to plugins for step-level reporting, enabling granular report data including per-step timing','Enables step counting','A debug mode'],answer:1,explanation:'stepNotifications=true enables step-level events in plugins (e.g., for Allure or custom reports). Default false for performance. Required for reports that show individual step pass/fail status.'},
{id:3633,topic:'cucumber',difficulty:'intermediate',question:'How does Cucumber find step definitions in a multi-module Maven project?',options:['Automatically across modules','Configure glue to include all relevant packages. In a shared library module, publish step definitions as a jar and add to test dependencies. All packages in glue are scanned recursively.','Not possible in multi-module','Via a shared feature file'],answer:1,explanation:'Add the shared-steps module as a test dependency. Add its package to glue: glue={"com.shared.steps","com.app.steps"}. Cucumber scans all listed packages and their sub-packages for step definitions and hooks.'},
{id:3634,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber scenario outline `@` tag inheritance?',options:['Tags do not inherit','Tags on Scenario Outline inherit to all generated examples. Tags on individual Examples table rows apply only to that row\'s scenarios. Rows can have different tags.','Tags cannot be on Examples','Tags only apply to Features'],answer:1,explanation:'Scenario Outline @smoke: all generated scenarios are @smoke. Examples @production: only that examples table\'s scenarios are @production. This enables fine-grained tag-based filtering of parameterized scenarios.'},
{id:3635,topic:'cucumber',difficulty:'intermediate',question:'What is Cucumber Scenario tagging strategy best practice?',options:['One tag per scenario maximum','Use functional tags (@smoke, @regression, @critical), story tags (@US-123), environment tags (@staging, @production), and state tags (@wip, @flaky). Keep tags consistent and documented.','Random tags','Tags by test owner'],answer:1,explanation:'Tag taxonomy: @smoke (fast health check), @regression (full suite), @api/@ui (test type), @US-1234 (user story link), @slow (de-prioritized in fast CI), @flaky (known issues). Document your tagging conventions.'},
{id:3636,topic:'cucumber',difficulty:'intermediate',question:'What does `DataTable.transpose()` do in Cucumber?',options:['Rotates the table','Transposes the rows and columns of a DataTable, converting column-oriented data to row-oriented. Useful when feature file data is more readable in column format.','Sorts the table','Filters the table'],answer:1,explanation:'dt.transpose() swaps rows and columns. Feature: | name | Alice | Bob |; | age | 30 | 25 |. After transpose: first column = headers. Useful when it is more natural to write data column-wise in Gherkin.'},
{id:3637,topic:'cucumber',difficulty:'advanced',question:'What is the Cucumber `io.cucumber.core.feature.FeatureWithLines` API?',options:['A file API','A low-level API for specifying exact feature:line references for running specific scenarios, used programmatically or via the @features path with line numbers','A feature file parser','A Gherkin validator'],answer:1,explanation:'features="src/test/resources/features/login.feature:15:42" runs only the scenarios at lines 15 and 42. Used with rerun.txt or for targeted debugging. Useful when running a single failing scenario.'},
{id:3638,topic:'cucumber',difficulty:'intermediate',question:'What is the `@CucumberOptions` `extraGlue` attribute?',options:['Additional Gherkin keywords','Adds extra glue packages on top of those configured in @CucumberOptions, useful for adding shared steps without replacing the existing glue configuration in a base class','Extra imports','Additional plugin paths'],answer:1,explanation:'extraGlue={"com.shared.steps"} adds extra scan paths without removing the glue defined elsewhere. Useful when extending a base runner class that already defines glue.'},
{id:3639,topic:'cucumber',difficulty:'intermediate',question:'What is the `Scenario.log(String)` method?',options:['A Java log call','Appends text output to the scenario\'s log in the Cucumber report, similar to Reporter.log() in TestNG but for Cucumber scenarios','A console print','A debug method'],answer:1,explanation:'scenario.log("User created with ID: " + userId) adds text to the report for the scenario. Visible in HTML reports under the scenario output. Use for traceability and debugging information.'},
{id:3640,topic:'cucumber',difficulty:'intermediate',question:'What is a Cucumber "step library" pattern?',options:['A step registry','A pattern where generic, reusable step implementations are extracted into a library module or base class, shared across multiple test projects or features','A step catalog','A step factory'],answer:1,explanation:'Step library: a shared module with @When("I click {string}"), @Then("I see {string}"), etc. Multiple test projects import it. Reduces duplication. Step library methods delegate to page objects or services.'},
{id:3641,topic:'cucumber',difficulty:'intermediate',question:'What is a Cucumber DSL (Domain Specific Language)?',options:['A programming language','The set of project-specific Gherkin vocabulary defined for a particular domain, creating a ubiquitous language shared between business and technical teams','A Gherkin extension','A step pattern library'],answer:1,explanation:'BDD DSL example for banking: "Given account ABC has balance $1000", "When I transfer $500 to DEF", "Then account ABC should have $500". The domain terms (account, balance, transfer) form the DSL.'},
{id:3642,topic:'cucumber',difficulty:'intermediate',question:'What is the `@CucumberContextConfiguration` annotation?',options:['A Spring Boot annotation','Marks a class as the Cucumber context configuration for Spring integration, telling Cucumber which class holds the Spring context setup (@SpringBootTest, @ContextConfiguration)','A TestNG configuration','A JUnit configuration'],answer:1,explanation:'@CucumberContextConfiguration @SpringBootTest public class CucumberSpringConfiguration {}. Without this marker, Cucumber cannot find the Spring configuration class. It is the integration point between Cucumber and Spring Test.'},
{id:3643,topic:'cucumber',difficulty:'intermediate',question:'What is `Scenario.getStatus()` used for in Cucumber?',options:['A numeric status code','Returns the current status of the scenario as a Status enum: PASSED, FAILED, SKIPPED, PENDING, UNDEFINED, AMBIGUOUS. Available in @After hooks.','The HTTP status code','A step count'],answer:1,explanation:'scenario.getStatus() in @After: if(scenario.getStatus() == Status.FAILED){ captureScreenshot(); }. More type-safe than isFailed(). Status.SKIPPED indicates intentionally skipped steps.'},
{id:3644,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber `@Before(value, order)` full syntax?',options:['No order or value','@Before(value="@tagExpression", order=N): value filters which scenarios trigger this hook; order controls execution sequence among multiple @Before hooks','Only order is supported','Only value is supported'],answer:1,explanation:'@Before(value="@web and not @api", order=1) runs for web scenarios not tagged @api, executes first. Multiple @Before hooks across classes are ordered by the order attribute (lower = earlier).'},
{id:3645,topic:'cucumber',difficulty:'intermediate',question:'What is the `DataTable.diff()` method in Cucumber?',options:['Shows table changes','Compares expected DataTable with actual data, throwing an exception with a clear diff output if they do not match. Used for table-based assertions.','Filters table rows','Merges two tables'],answer:1,explanation:'DataTable expected = dataTable; DataTable actual = DataTable.create(actualData); expected.diff(actual) — if data differs, throws a detailed diff exception. Great for asserting database query results against expected tables.'},
{id:3646,topic:'cucumber',difficulty:'intermediate',question:'What is the `@CucumberOptions` `publish` flag?',options:['Publishes to a Maven repo','publish=true uploads test results to the Cucumber Reports portal (reports.cucumber.io) after the run, generating a shareable public URL. Requires acceptance of their terms.','Publishes to npm','Publishes to GitHub Pages'],answer:1,explanation:'@CucumberOptions(publish=true) or CUCUMBER_PUBLISH_TOKEN env var for authenticated reports. After the run, Cucumber prints the report URL. Free tier reports expire after 24 hours. Useful for quick sharing.'},
{id:3647,topic:'cucumber',difficulty:'intermediate',question:'What is the `io.cucumber.java8` package?',options:['A Java 8 parser','A Java 8 lambda-based API for writing step definitions as lambda expressions instead of annotated methods: StaticHooks.before(()->driver=new ChromeDriver()). More concise but less IDE support.','A Java 8 compatibility layer','A lambda testing API'],answer:1,explanation:'Java 8 API: implements StepDefinitionBody: LambdaGlue class implements En: Before(()->setup()); Given("step {string}", (String s)->doSomething(s)). Less common in enterprise but reduces boilerplate.'},
{id:3648,topic:'cucumber',difficulty:'advanced',question:'What is the Cucumber SPI (Service Provider Interface) for plugins?',options:['A Spring SPI','A Java SPI mechanism where plugins are registered by adding META-INF/services/io.cucumber.plugin.Plugin with the plugin class name, auto-discovered by Cucumber without @CucumberOptions','A Maven SPI','A Gradle SPI'],answer:1,explanation:'Create META-INF/services/io.cucumber.plugin.Plugin with your plugin class. Cucumber auto-loads it. Useful for always-on plugins (e.g., enterprise reporting) that should not require each project to configure them.'},
{id:3649,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber `@Given` annotation\'s value attribute?',options:['A description field','The step pattern: either a Cucumber Expression ({string}, {int}) or a regular expression (prefixed with ^/$). Must uniquely match a Gherkin step.','A priority field','A timeout field'],answer:1,explanation:'@Given("the user {string} has {int} items in cart") — Cucumber Expression. @Given("^the user (.*) has (\\\\d+) items in cart$") — regular expression. Pattern must uniquely identify the step.'},
{id:3650,topic:'cucumber',difficulty:'intermediate',question:'What is Cucumber\'s `@DataTableType` annotation?',options:['A DataTable format annotation','Registers a method that converts DataTable rows/cells to custom Java types, enabling type-safe DataTable parameters in step definitions','A custom DataTable format','A serialization annotation'],answer:1,explanation:'@DataTableType public User user(Map<String,String> entry){ return new User(entry.get("name"), entry.get("email")); } enables: public void users(List<User> users). Cucumber auto-converts table rows to User objects.'},
{id:3651,topic:'cucumber',difficulty:'intermediate',question:'What is Cucumber\'s `@DocStringType` annotation?',options:['A DocString format','Registers a method that converts DocString content to a custom Java type: @DocStringType public JsonNode json(String content){ return mapper.readTree(content); }','A string formatter','A markdown parser'],answer:1,explanation:'@DocStringType(contentType="json") public RequestBody body(String json){ return parse(json); } enables: When the request body is: """json { ... } """ — step receives RequestBody directly.'},
{id:3652,topic:'cucumber',difficulty:'intermediate',question:'What happens when a Cucumber scenario step fails?',options:['Continues to next step','The failed step marks the scenario as FAILED, subsequent steps are SKIPPED (not executed), but @After hooks always run regardless of failure','Retries the step','Throws a Java exception and stops the JVM'],answer:1,explanation:'On step failure: scenario = FAILED, remaining steps = SKIPPED. @After hooks always run (important for cleanup). The failure exception is reported in the JSON/HTML reports. Stack trace is included in the output.'},
{id:3653,topic:'cucumber',difficulty:'intermediate',question:'What is `io.cucumber.datatable.DataTable.emptyDataTable()`?',options:['Returns null','Returns an empty DataTable instance with no rows or columns, useful as a default argument in step definitions that accept optional tables','Clears a data table','Returns a zero-row table'],answer:1,explanation:'emptyDataTable() creates a DataTable with zero rows. Useful in optional DataTable step definitions where you want to handle "no table provided" gracefully without null checks.'},
{id:3654,topic:'cucumber',difficulty:'intermediate',question:'What is the recommended project structure for a Cucumber-JVM project?',options:['All in src/main/java','src/test/java for step definitions and runner; src/test/resources/features for .feature files; src/test/resources/junit-platform.properties for JUnit 5 config','All in src/test/resources','All in src/main/resources'],answer:1,explanation:'Standard Maven layout: src/test/java/com/myapp/steps/ (step defs), src/test/java/com/myapp/runners/ (runner class), src/test/resources/features/ (.feature files), src/test/resources/junit-platform.properties (JUnit 5 config).'},
{id:3655,topic:'cucumber',difficulty:'intermediate',question:'What is `@CucumberOptions` `objectFactory` attribute?',options:['Sets the runner factory','Specifies a custom ObjectFactory class for creating step definition instances, overriding the default (PicoContainer if on classpath, default if not)','A DI configuration','A test factory'],answer:1,explanation:'objectFactory=SpringObjectFactory.class or a custom class. Rarely needed — having cucumber-spring on classpath auto-selects SpringObjectFactory. Use when you need custom lifecycle beyond built-in DI options.'},
{id:3656,topic:'cucumber',difficulty:'intermediate',question:'How do you run a single Cucumber feature file from the command line with Maven?',options:['Not possible from CLI','mvn test -Dcucumber.features="src/test/resources/features/login.feature" overrides the features path at runtime','Use a Maven profile','Edit @CucumberOptions each time'],answer:1,explanation:'System property overrides: -Dcucumber.features, -Dcucumber.filter.tags, -Dcucumber.filter.name, -Dcucumber.glue, -Dcucumber.plugin. All @CucumberOptions can be overridden by system properties at runtime.'},
{id:3657,topic:'cucumber',difficulty:'advanced',question:'What is the Cucumber JUnit 5 `parallel.execution.unit` configuration?',options:['A JUnit setting','Controls parallel execution granularity: FEATURE (each feature in a thread), SCENARIO (each scenario in a thread). Set in junit-platform.properties: cucumber.execution.parallel.config.strategy=fixed','A Surefire setting','A Cucumber annotation'],answer:1,explanation:'junit-platform.properties: cucumber.execution.parallel.enabled=true; cucumber.execution.parallel.config.strategy=fixed; cucumber.execution.parallel.config.fixed.parallelism=4; cucumber.execution.execution-mode.feature=same_thread for scenario-level parallelism within features.'},
{id:3658,topic:'cucumber',difficulty:'intermediate',question:'What does `@CucumberOptions` `wip` (obsolete) do?',options:['A current feature','Historically ran only scenarios tagged @wip and failed if any passed. Removed in Cucumber 4+. Replaced by tag expressions: tags="@wip" and checking results manually.','Marks work in progress','A build flag'],answer:1,explanation:'The wip option is removed in Cucumber 4+. Old behavior: run only @wip tagged scenarios, fail if any pass (forcing you to update @wip). Modern approach: use tag expressions and CI policy to manage @wip scenarios.'},
{id:3659,topic:'cucumber',difficulty:'intermediate',question:'What is the `CucumberOptions` difference between `features` and `glue`?',options:['They are the same','features: path to .feature files (resources). glue: Java package containing step definitions, hooks, and configuration classes. They must both be correctly configured for Cucumber to connect steps to implementations.','features is a class path','glue is a resource path'],answer:1,explanation:'features is a filesystem/classpath path to .feature files (src/test/resources/features). glue is a Java package name (com.myapp.steps). Getting either wrong causes "No step definitions" or "Feature files not found" errors.'},
{id:3660,topic:'cucumber',difficulty:'intermediate',question:'What is the Cucumber `@AfterSuite` equivalent in JUnit 5 Cucumber?',options:['@AfterSuite annotation in Cucumber','Use JUnit 5 @AfterAll in an extension or in the @Suite runner class. Cucumber-JVM has no native suite-level teardown hook — use JUnit 5 lifecycle annotations in the runner.','A Cucumber plugin','A Spring shutdown hook'],answer:1,explanation:'JUnit 5 @Suite class: @AfterAll static void suiteCleanup(){ extent.flush(); } — runs after all tests. Or use a Cucumber plugin\'s EventListener for TestRunFinished event for suite-level teardown in a framework-agnostic way.'}
]);
